(function(r,f){const m=f();if(typeof module==='object')module.exports=m;else r.Model=m})(globalThis,()=>{const KEY='ob.notes.v1';function empty(){return{version:1,revision:0,notes:[]}}function validate(s){if(!s||s.version!==1||!Number.isSafeInteger(s.revision)||s.revision<0||!Array.isArray(s.notes)||s.notes.length>50)throw Error('Invalid notes store');let size=0;const ids=new Set();for(const x of s.notes){if(typeof x.id!=='string'||!/^[A-Za-z0-9_-]{1,64}$/.test(x.id)||ids.has(x.id)||typeof x.title!=='string'||!x.title.trim()||x.title.length>120||typeof x.body!=='string'||x.body.length>10000||x.body.includes('\0'))throw Error('Invalid note');ids.add(x.id);size+=x.title.length+x.body.length}if(size>250000)throw Error('Notes storage limit reached');return structuredClone(s)}function save(s,n){s=validate(s);const i=s.notes.findIndex(x=>x.id===n.id);if(i<0)s.notes.unshift(n);else s.notes[i]=n;s.revision++;return validate(s)}function remove(s,id){s=validate(s);if(!s.notes.some(x=>x.id===id))throw Error('Note no longer exists');s.notes=s.notes.filter(x=>x.id!==id);s.revision++;return s}function load(storage){const raw=storage.getItem(KEY);if(raw&&raw.length>1600000)throw Error('Oversized store');return raw?validate(JSON.parse(raw)):empty()}function commit(storage,before,next){if(load(storage).revision!==before.revision)throw Error('Notes changed elsewhere. Reload saved notes before saving.');storage.setItem(KEY,JSON.stringify(validate(next)));return next}function text(n){const s=validate({version:1,revision:0,notes:[n]});return s.notes[0].title+'\n\n'+s.notes[0].body+'\n'}return{KEY,empty,validate,save,remove,load,commit,text}});
